/**
 * Wire Placement Module Solver for Keep Talking and Nobody Explains
 *
 * Paste this game's table (once per game: it changes) and the module picture. The colour of the
 * wire on C3 picks the column; every wire whose colour and one of its two ends match a row in that
 * column is cut. Any misread wire or table cell can be fixed by hand.
 */
(function () {
  'use strict';

  // ── Reading and solving: bomb_boomed's (window.BombLogic.wireplace, bomb-logic.js) ──
  // Generated by bomb_boomed's scripts/build-conso-logic.mjs: re-run it to sync, don't copy code here.
  const { classifyWirePicture, solveWirePlacement, wireLabel, cap, CELLS, PICK_COLORS, SAMPLE_TABLE, SAMPLE_WIRES } = window.BombLogic.wireplace;
  const K = window.ModuleKit;
  const { $, esc } = K;

  const SWATCH = { black: '#141414', blue: '#2f7fe0', red: '#e0352b', white: '#f1f1f1', yellow: '#f2c531', green: '#3a9d5d', orange: '#e07b1f', purple: '#8e44ad' };

  const state = {
    table: null, // { columns: [colour], rows: [{ color, cells: [code] }], unsure: [[r, c]] } — this game's
    wires: [],   // [{ color, a, b }]
    status: { text: '', ok: null },
    thumbs: { table: '', board: '' },
    adding: { a: 'A1', b: 'B1', color: 'yellow' }
  };
  window.wireplaceModuleState = state;

  function injectStyles() {
    K.injectBase();
    if ($('wireplaceStyles')) return;
    const style = document.createElement('style');
    style.id = 'wireplaceStyles';
    style.textContent = `
    .wp-board-wrap { display: flex; flex-wrap: wrap; gap: 14px; align-items: flex-start; margin-bottom: 14px; }
    .wp-board { width: 230px; max-width: 100%; height: auto; background: #1f2228; border-radius: 10px; border: 1px solid #2a2f5c; }
    .wp-lbl { fill: #ffd875; font: 700 13px 'JetBrains Mono', ui-monospace, monospace; text-anchor: middle; }
    .wp-tile { fill: #3a3f48; }
    .wp-tile.c3 { stroke: #ffd875; stroke-width: 2; }
    .wp-peg { fill: #9aa0a8; }
    .wp-line { stroke-width: 7; stroke-linecap: round; }
    .wp-line-edge { stroke: #8a9099; stroke-width: 10; stroke-linecap: round; }
    .wp-wire.keep { opacity: .35; }
    .wp-cut-halo { stroke: #ff5252; stroke-width: 13; stroke-linecap: round; opacity: .55; }
    .wp-scissors { fill: #fff; font-size: 15px; text-anchor: middle; paint-order: stroke; stroke: #000; stroke-width: 3px; }
    .wp-why { list-style: none; margin: 0; padding: 0; font: 12px 'JetBrains Mono', ui-monospace, monospace; color: #8892b0; line-height: 1.7; flex: 1 1 220px; }
    .wp-why li.cut { color: #e2e8f0; }
    .wp-why li.cut b { color: #ff6b6b; }
    .wp-dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 6px; border: 1px solid #777; vertical-align: -1px; }
    .wp-wire-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; font-size: 12px; margin-bottom: 6px; }
    .wp-wire-row.add { margin-top: 8px; padding-top: 8px; border-top: 1px dashed #2a2f5c; }
    .wp-color { border-left: 6px solid var(--wp-c, #2a2f5c) !important; min-width: 82px; }
    .wp-cell.unsure { border-color: #ef4444; box-shadow: 0 0 0 1px #ef4444 inset; }
    .wp-table tr.on td.used { background: rgba(255,82,82,.22); }
    `;
    document.head.appendChild(style);
  }

  function renderUI() {
    const section = $('wireplaceSection');
    if (!section) return;
    section.innerHTML = `
      <div class="mk-shell">
        <div class="mk-head">
          <div class="mk-title"><span>〰️</span> Wire Placement Solver <span class="mk-pill">C3 picks the column</span></div>
          <div class="mk-actions">
            <button class="mk-btn" type="button" data-act="clear">Clear board</button>
            <button class="mk-btn" type="button" data-act="clear-table" id="wireplaceClearTable">Clear table</button>
            <button class="mk-btn gold" type="button" data-act="sample">⚡ Sample</button>
          </div>
        </div>
        <div class="mk-layout">
          <div>
            <div class="mk-card">
              <div class="mk-card-title">Paste Pictures</div>
              <input type="file" id="wireplaceFileInput" accept="image/*" multiple style="display:none;">
              <div id="wireplaceDropzone" class="mk-dropzone">
                <div class="mk-drop-icon">〰️ A1 → C3</div>
                <div class="mk-drop-title">Click, drop or <kbd>Ctrl+V</kbd> the table and the module picture</div>
                <div class="mk-drop-sub">the <b>table</b> stays for the whole game · the <b>module</b> picture is per bomb · both at once works too</div>
              </div>
              <div id="wireplaceStatus"></div>
              <div class="mk-row"><span class="mk-label">Table</span><span id="wireplaceTableInfo"></span></div>
              <div class="mk-row"><span class="mk-label">Board</span><span id="wireplaceBoardInfo"></span></div>
            </div>
            <details class="mk-details">
              <summary>Board — fix a misread wire</summary>
              <div id="wireplaceWires"></div>
            </details>
          </div>
          <div>
            <div class="mk-banner">
              <div class="mk-banner-row">
                <div>
                  <div class="mk-banner-lbl">Cut</div>
                  <div id="wireplaceAnswer" class="mk-answer lines"></div>
                  <div id="wireplaceStats" class="mk-stats"></div>
                </div>
                <button id="wireplaceCopyBtn" class="mk-btn gold" type="button" data-act="copy">📋 Copy</button>
              </div>
            </div>
            <div id="wireplaceBoard"></div>
            <details class="mk-details" open>
              <summary>Table — the C3 colour's column is used · fix any misread cell</summary>
              <div id="wireplaceTable"></div>
            </details>
          </div>
        </div>
      </div>`;
    K.wirePictures({ sectionId: 'wireplaceSection', dropzoneId: 'wireplaceDropzone', inputId: 'wireplaceFileInput', onPictures: readPictures });
    section.addEventListener('click', onClick);
    section.addEventListener('change', onChange);
    update();
  }

  const colorPick = (value, attrs, title) => `
    <select class="mk-select wp-color" ${attrs} title="${esc(title)}" style="--wp-c: ${SWATCH[value] || 'transparent'};">
      ${value ? '' : '<option value="">?</option>'}${PICK_COLORS.map(c => `<option value="${c}"${c === value ? ' selected' : ''}>${cap(c)}</option>`).join('')}
    </select>`;
  const cellPick = (value, attrs, extra = '') => `
    <select class="mk-select wp-cell ${extra}" ${attrs}>${CELLS.map(c => `<option${c === value ? ' selected' : ''}>${c}</option>`).join('')}</select>`;

  function readPictures(items) {
    const notes = [];
    let bad = false;
    for (const { img, uri } of items) {
      try {
        const r = classifyWirePicture(K.imageData(img));
        if (r.type === 'table') {
          state.table = { columns: r.table.columns, rows: r.table.rows, unsure: r.table.unsure };
          state.thumbs.table = uri;
          const odd = r.table.unsure.length + r.table.columns.filter(c => !c).length + r.table.rows.filter(x => !x.color).length;
          notes.push(`✓ Table read: ${r.table.rows.length} rows × ${r.table.columns.length} colours${odd ? ` · ${odd} cell${odd === 1 ? '' : 's'} unsure — marked in the table` : ''}`);
          if (odd) bad = true;
        } else if (r.type === 'board') {
          state.wires = r.board.wires.map(({ color, a, b }) => ({ color, a, b }));
          state.thumbs.board = uri;
          notes.push(`✓ Board: ${r.board.wires.length} wires`);
        } else {
          notes.push(`⚠ ${r.reason || 'Not a Wire Placement picture.'}`);
          bad = true;
        }
      } catch (e) {
        notes.push(`⚠ ${e.message || 'Could not read that picture.'}`);
        bad = true;
      }
    }
    state.status = { text: notes.join('  ·  '), ok: !bad };
    update();
  }

  function onClick(e) {
    const b = e.target.closest('[data-act]');
    if (!b || b.tagName === 'SELECT') return;
    const act = b.dataset.act;
    if (act === 'copy') { K.copyText(solve().copy, b, '📋 Copy'); return; }
    if (act === 'sample') {
      state.table = SAMPLE_TABLE;
      state.wires = SAMPLE_WIRES.map(w => ({ ...w }));
      state.status = { text: 'Sample: the 23 Nov table and board (C3 is blue → cut A1-A2 yellow).', ok: true };
    } else if (act === 'clear') {
      state.wires = [];
      state.thumbs.board = '';
      state.status = { text: state.table ? 'Board cleared — the table stays for this game.' : '', ok: null };
    } else if (act === 'clear-table') {
      state.table = null; state.thumbs.table = ''; state.status = { text: 'Table cleared.', ok: null };
    } else if (act === 'wire-x') {
      state.wires = state.wires.filter((_, j) => j !== Number(b.dataset.i));
    } else if (act === 'wire-add') {
      const w = state.adding;
      if (w.a !== w.b) state.wires = [...state.wires, { ...w }];
    } else return;
    update();
  }

  function onChange(e) {
    const s = e.target, d = s.dataset, v = s.value;
    const t = state.table && { ...state.table }; // edited as a copy (the sample table stays as it is)
    if (d.act === 'wire') {
      const i = Number(d.i);
      state.wires = state.wires.map((w, j) => (j === i ? { ...w, [d.f]: v || null } : w));
    } else if (d.act === 'adding') {
      state.adding = { ...state.adding, [d.f]: v };
    } else if (d.act === 'col' && t) {
      t.columns = t.columns.map((x, j) => (j === Number(d.c) ? v || null : x));
    } else if (d.act === 'rowcolor' && t) {
      t.rows = t.rows.map((row, i) => (i === Number(d.r) ? { ...row, color: v || null } : row));
    } else if (d.act === 'tcell' && t) {
      const r = Number(d.r), c = Number(d.c);
      t.rows = t.rows.map((row, i) => (i === r ? { ...row, cells: row.cells.map((x, j) => (j === c ? v || null : x)) } : row));
      t.unsure = (t.unsure || []).filter(([rr, cc]) => rr !== r || cc !== c);
    } else return;
    if (t) state.table = t;
    update();
  }

  const solve = () => solveWirePlacement(state.table, state.wires);

  /** The 4×4 board as the defuser sees it: cut wires bold with ✂, the rest faded. */
  function boardSvg(res) {
    const P = 46, M = 26;
    const at = (n) => ({ x: M + 'ABCD'.indexOf(n[0]) * P + P / 2, y: M + (Number(n[1]) - 1) * P + P / 2 });
    const cutSet = new Set(res.ready ? res.cut : []);
    let g = '';
    'ABCD'.split('').forEach((c, i) => { g += `<text x="${M + i * P + P / 2}" y="16" class="wp-lbl">${c}</text>`; });
    [1, 2, 3, 4].forEach((r, i) => { g += `<text x="10" y="${M + i * P + P / 2 + 4}" class="wp-lbl">${r}</text>`; });
    CELLS.forEach(n => { const p = at(n); g += `<rect x="${p.x - P / 2 + 3}" y="${p.y - P / 2 + 3}" width="${P - 6}" height="${P - 6}" rx="6" class="wp-tile ${n === 'C3' ? 'c3' : ''}"/>`; });
    state.wires.forEach(w => {
      if (!CELLS.includes(w.a) || !CELLS.includes(w.b)) return;
      const a = at(w.a), b = at(w.b), cut = cutSet.has(w);
      g += `<g class="wp-wire ${res.ready ? (cut ? 'cut' : 'keep') : ''}">`;
      if (cut) g += `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" class="wp-cut-halo"/>`;
      if (w.color === 'black') g += `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" class="wp-line-edge"/>`;
      g += `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${SWATCH[w.color] || '#888'}" class="wp-line"/>`;
      if (cut) g += `<text x="${(a.x + b.x) / 2}" y="${(a.y + b.y) / 2 + 5}" class="wp-scissors">✂</text>`;
      g += '</g>';
    });
    CELLS.forEach(n => { const p = at(n); g += `<circle cx="${p.x}" cy="${p.y}" r="4.5" class="wp-peg"/>`; });
    return `<svg class="wp-board" viewBox="0 0 ${M + 4 * P + 6} ${M + 4 * P + 6}" role="img" aria-label="Wire Placement board">${g}</svg>`;
  }

  function tableHtml(res) {
    const t = state.table;
    if (!t) return '<div class="mk-dim">No table yet — paste this game\'s Wire Placement table picture (or press Sample).</div>';
    const matched = new Set();
    if (res.ready) res.verdicts.forEach(v => v.rows.forEach(r => matched.add(r)));
    const isUnsure = (r, c) => (t.unsure || []).some(([rr, cc]) => rr === r && cc === c);
    return `<div class="mk-table-wrap"><table class="mk-table wp-table">
      <thead><tr><th>C3 wire is →<br>Cut wire ↓</th>${t.columns.map((c, j) => `<th class="${j === res.column ? 'used' : ''}">${colorPick(c, `data-act="col" data-c="${j}"`, 'Column colour (C3 wire)')}</th>`).join('')}</tr></thead>
      <tbody>${t.rows.map((row, r) => `<tr class="${matched.has(r) ? 'on' : ''}">
        <td>${colorPick(row.color, `data-act="rowcolor" data-r="${r}"`, 'Cut-wire colour of this row')}</td>
        ${row.cells.map((code, c) => `<td class="${c === res.column ? 'used' : ''}">
          <select class="mk-select wp-cell ${isUnsure(r, c) ? 'unsure' : ''}" data-act="tcell" data-r="${r}" data-c="${c}" title="${isUnsure(r, c) ? 'Not sure about this one — check it' : 'Fix this cell if it was misread'}">
            <option value="">·</option>${CELLS.map(x => `<option${x === code ? ' selected' : ''}>${x}</option>`).join('')}
          </select></td>`).join('')}
      </tr>`).join('')}</tbody></table></div>`;
  }

  function update() {
    if (!$('wireplaceAnswer')) return;
    const res = solve();
    const t = state.table, wires = state.wires;

    $('wireplaceStatus').innerHTML = state.status.text ? `<div class="mk-status ${state.status.ok === false ? 'bad' : state.status.ok ? 'ok' : ''}">${esc(state.status.text)}</div>` : '';
    $('wireplaceTableInfo').innerHTML = (t ? `<span class="mk-ok">read ✓ ${t.rows.length} rows × ${t.columns.length} colours</span>` : '<span class="mk-need">paste this game\'s table picture (it can change every game)</span>')
      + (state.thumbs.table ? ` <img class="mk-thumb" src="${state.thumbs.table}" alt="table">` : '');
    $('wireplaceBoardInfo').innerHTML = (wires.length ? `<span class="mk-ok">${wires.length} wires${res.c3 ? ` · C3 ${esc(res.c3.color)}` : ' · no wire on C3'}</span>` : '<span class="mk-need">paste the module picture</span>')
      + (state.thumbs.board ? ` <img class="mk-thumb" src="${state.thumbs.board}" alt="board">` : '');
    $('wireplaceClearTable').disabled = !t;

    const placeholder = !t ? "PASTE THIS GAME'S WIRE PLACEMENT TABLE" : !wires.length ? 'PASTE THE MODULE PICTURE' : res.reason ? res.reason.toUpperCase() : '— — —';
    $('wireplaceAnswer').innerHTML = res.ready
      ? (res.cut.length ? res.cut.map(w => `<div>✂ ${esc(wireLabel(w))}</div>`).join('') : '<div>CUT NOTHING</div>')
      : `<span class="ph">${esc(placeholder)}</span>`;
    $('wireplaceStats').textContent = res.ready
      ? `C3 is ${res.c3.color} → ${res.c3.color} column · ${res.cut.length} of ${wires.length} cut`
      : 'The colour of the C3 wire picks the column';
    $('wireplaceCopyBtn').disabled = !res.ready;

    $('wireplaceBoard').innerHTML = wires.length ? `<div class="wp-board-wrap">${boardSvg(res)}${res.ready ? `<ul class="wp-why">${res.verdicts.map(v => `
      <li class="${v.cut ? 'cut' : ''}"><span class="wp-dot" style="background:${SWATCH[v.wire.color] || '#888'}"></span><b>${esc(v.wire.a)}-${esc(v.wire.b)}</b> ${esc(v.wire.color)}: ${v.cut ? `CUT (row ${v.rows.map(r => r + 1).join(', ')}: ${esc(cap(v.wire.color))} ${esc(t.rows[v.rows[0]].cells[res.column])})` : 'leave'}</li>`).join('')}</ul>` : ''}</div>` : '';

    const add = state.adding;
    $('wireplaceWires').innerHTML = wires.map((w, i) => `
      <div class="wp-wire-row">
        ${colorPick(w.color, `data-act="wire" data-i="${i}" data-f="color"`, 'Wire colour')}
        ${cellPick(w.a, `data-act="wire" data-i="${i}" data-f="a"`)} <span>–</span> ${cellPick(w.b, `data-act="wire" data-i="${i}" data-f="b"`)}
        <button type="button" class="mk-x" data-act="wire-x" data-i="${i}" title="Remove this wire">✕</button>
      </div>`).join('') + `
      <div class="wp-wire-row add">
        ${colorPick(add.color, 'data-act="adding" data-f="color"', 'New wire colour')}
        ${cellPick(add.a, 'data-act="adding" data-f="a"')} <span>–</span> ${cellPick(add.b, 'data-act="adding" data-f="b"')}
        <button type="button" class="mk-btn small" data-act="wire-add">+ add wire</button>
      </div>`;

    $('wireplaceTable').innerHTML = tableHtml(res);
  }

  window.initWireplaceModule = function () {
    injectStyles();
    renderUI();
  };
})();
